# ============================================================================
# Lastovo miniCOI — final rarefied alpha-diversity models and figure
# ============================================================================
# Inputs are generated by 02_qiime2_rarefied_alpha.sh.
# Final manuscript models:
#   Observed ASV richness ~ ITW + layer + mesh : negative-binomial GLM
#   Shannon diversity     ~ ITW + layer + mesh : linear model
# P values are Holm-adjusted across all six reported alpha coefficients.
# ============================================================================

required <- c("MASS", "AER", "car", "ggplot2", "patchwork")
missing <- required[!vapply(required, requireNamespace, logical(1), quietly = TRUE)]
if (length(missing)) {
  stop("Install missing R package(s): ", paste(missing, collapse = ", "))
}

suppressPackageStartupMessages({
  library(MASS)
  library(AER)
  library(car)
  library(ggplot2)
  library(patchwork)
})

args0 <- commandArgs(trailingOnly = FALSE)
filearg <- sub("^--file=", "", args0[grep("^--file=", args0)])
ROOT <- if (length(filearg)) {
  normalizePath(file.path(dirname(filearg[1]), ".."))
} else {
  normalizePath(getwd())
}

obs_file  <- file.path(ROOT, "exports", "alpha_observed", "alpha-diversity.tsv")
sha_file  <- file.path(ROOT, "exports", "alpha_shannon", "alpha-diversity.tsv")
meta_file <- file.path(ROOT, "metadata", "COI_metadata_original.tsv")
out       <- file.path(ROOT, "results")
dir.create(out, showWarnings = FALSE, recursive = TRUE)

for (f in c(obs_file, sha_file, meta_file)) {
  if (!file.exists(f)) stop("Missing required input: ", f)
}

read_alpha <- function(path, value_name) {
  x <- read.delim(
    path,
    sep = "\t",
    header = TRUE,
    check.names = FALSE,
    quote = "",
    comment.char = "",
    stringsAsFactors = FALSE
  )
  if (ncol(x) < 2) stop("Unexpected alpha-diversity file format: ", path)

  y <- data.frame(
    sample_id = as.character(x[[1]]),
    value = suppressWarnings(as.numeric(x[[2]])),
    stringsAsFactors = FALSE
  )
  if (anyNA(y$value)) stop("Non-numeric alpha-diversity value in: ", path)
  names(y)[2] <- value_name
  y
}

meta <- read.delim(
  meta_file,
  sep = "\t",
  header = TRUE,
  check.names = FALSE,
  quote = "",
  comment.char = "",
  stringsAsFactors = FALSE
)
names(meta)[1] <- "sample_id"

obs <- read_alpha(obs_file, "Observed_ASVs")
sha <- read_alpha(sha_file, "Shannon")

dat <- Reduce(function(x, y) merge(x, y, by = "sample_id"), list(obs, sha, meta))
dat <- dat[dat$layer %in% c("upper", "lower"), , drop = FALSE]
if (nrow(dat) != 19) stop("Expected 19 samples after N12 exclusion; found ", nrow(dat))

# Reference levels are the manuscript reference levels.
dat$ITW_model <- factor(
  ifelse(tolower(dat$ITW) == "itw", "ITW", "noITW"),
  levels = c("ITW", "noITW")
)
dat$Layer_model <- factor(dat$layer, levels = c("upper", "lower"))
dat$Mesh_model <- factor(
  ifelse(dat$fraction == "micro", "53", "200"),
  levels = c("53", "200")
)

# ---------------------------------------------------------------------------
# Model-choice diagnostic for count-valued richness
# ---------------------------------------------------------------------------
# Lucija Kanjer's alpha-modelling template explicitly checked Poisson
# overdispersion before using a negative-binomial model. We retain that useful
# diagnostic here, while keeping the NB model as the prespecified manuscript
# model so that the published analysis is reproduced exactly.
pois <- glm(
  Observed_ASVs ~ ITW_model + Layer_model + Mesh_model,
  family = poisson,
  data = dat
)
overdisp <- AER::dispersiontest(pois)

# Final manuscript models.
obs_model <- MASS::glm.nb(
  Observed_ASVs ~ ITW_model + Layer_model + Mesh_model,
  data = dat
)
sha_model <- lm(
  Shannon ~ ITW_model + Layer_model + Mesh_model,
  data = dat
)

coef_order <- c("ITW_modelnoITW", "Layer_modellower", "Mesh_model200")
factor_labels <- c("ITW occurrence", "Layer", "Mesh size")
contrast_labels <- c(
  "Without ITW activity vs with ITW activity",
  "Lower vs upper",
  "200 µm vs 53 µm"
)

extract_nb <- function(model) {
  sm <- coef(summary(model))[coef_order, , drop = FALSE]
  beta <- sm[, "Estimate"]
  se   <- sm[, "Std. Error"]

  data.frame(
    Metric = "Observed ASV richness",
    Method = "Negative-binomial GLM",
    Factor = factor_labels,
    Contrast = contrast_labels,
    Effect_measure = "IRR",
    Effect = exp(beta),
    CI_low = exp(beta - 1.96 * se),
    CI_high = exp(beta + 1.96 * se),
    Statistic = sm[, "z value"],
    p_raw = sm[, "Pr(>|z|)"],
    stringsAsFactors = FALSE
  )
}

extract_lm <- function(model) {
  sm <- coef(summary(model))[coef_order, , drop = FALSE]
  beta <- sm[, "Estimate"]
  se   <- sm[, "Std. Error"]

  data.frame(
    Metric = "Shannon diversity",
    Method = "Linear model",
    Factor = factor_labels,
    Contrast = contrast_labels,
    Effect_measure = "Estimate",
    Effect = beta,
    CI_low = beta - 1.96 * se,
    CI_high = beta + 1.96 * se,
    Statistic = sm[, "t value"],
    p_raw = sm[, "Pr(>|t|)"],
    stringsAsFactors = FALSE
  )
}

results <- rbind(extract_nb(obs_model), extract_lm(sha_model))
results$p_Holm_all6 <- p.adjust(results$p_raw, method = "holm")
results$N <- nrow(dat)
results$Rarefaction_depth <- 19000

write.csv(
  results,
  file.path(out, "alpha_model_results_rarefied.csv"),
  row.names = FALSE
)
write.csv(
  dat[, c("sample_id", "ITW", "layer", "fraction", "Observed_ASVs", "Shannon")],
  file.path(out, "alpha_values_rarefied.csv"),
  row.names = FALSE
)

# ---------------------------------------------------------------------------
# Multicollinearity diagnostic
# ---------------------------------------------------------------------------
vif_to_df <- function(model_name, model) {
  v <- car::vif(model)
  if (is.matrix(v)) {
    data.frame(
      Model = model_name,
      Term = rownames(v),
      VIF = v[, 1],
      Df = v[, 2],
      GVIF_scaled = v[, 3],
      row.names = NULL
    )
  } else {
    data.frame(
      Model = model_name,
      Term = names(v),
      VIF = as.numeric(v),
      Df = 1,
      GVIF_scaled = as.numeric(v),
      row.names = NULL
    )
  }
}

vifs <- rbind(
  vif_to_df("Observed richness NB", obs_model),
  vif_to_df("Shannon LM", sha_model)
)
write.csv(vifs, file.path(out, "alpha_VIF.csv"), row.names = FALSE)

# Text record of diagnostics/model summaries.
sink(file.path(out, "alpha_model_diagnostics.txt"))
cat("POISSON OVERDISPERSION DIAGNOSTIC\n")
print(overdisp)
cat("\nFINAL NEGATIVE-BINOMIAL MODEL\n")
print(summary(obs_model))
cat("\nTheta:", obs_model$theta, "\n")
cat("\nSHANNON LINEAR MODEL\n")
print(summary(sha_model))
cat("\nVIF\n")
print(vifs)
cat("\nREFERENCE LEVELS\n")
cat("ITW: with ITW activity\nLayer: upper\nMesh: 53 µm\n")
sink()

# Standard diagnostic plots.
png(file.path(out, "diagnostics_observed_NB.png"), width = 1800, height = 1800, res = 220)
par(mfrow = c(2, 2))
plot(obs_model)
dev.off()

png(file.path(out, "diagnostics_shannon_LM.png"), width = 1800, height = 1800, res = 220)
par(mfrow = c(2, 2))
plot(sha_model)
dev.off()

# ---------------------------------------------------------------------------
# Black-and-white alpha forest plot used for manuscript-style output
# ---------------------------------------------------------------------------
star <- function(p) {
  ifelse(p <= 0.001, "***", ifelse(p < 0.01, "**", ifelse(p < 0.05, "*", "")))
}

obs_res <- results[results$Metric == "Observed ASV richness", , drop = FALSE]
sha_res <- results[results$Metric == "Shannon diversity", , drop = FALSE]
term_labels <- c(
  "ITW occurrence\n[Without activity]",
  "Layer\n[Lower]",
  "Mesh size\n[200 µm]"
)

obs_res$term <- factor(term_labels, levels = rev(term_labels))
sha_res$term <- factor(term_labels, levels = rev(term_labels))
obs_res$label <- paste0(sprintf("%.2f", obs_res$Effect), " ", star(obs_res$p_Holm_all6))
sha_res$label <- paste0(sprintf("%.2f", sha_res$Effect), " ", star(sha_res$p_Holm_all6))

base_theme <- theme_bw(base_size = 12) +
  theme(
    legend.position = "none",
    panel.grid.minor = element_blank(),
    panel.grid.major.y = element_line(colour = "grey88", linewidth = 0.4),
    panel.grid.major.x = element_line(colour = "grey90", linewidth = 0.4),
    axis.text = element_text(colour = "black"),
    axis.title = element_text(colour = "black"),
    plot.title = element_text(size = 13, colour = "black"),
    plot.tag = element_text(face = "plain", size = 13, colour = "black")
  )

p_obs <- ggplot(obs_res, aes(y = term)) +
  geom_vline(xintercept = 1, linewidth = 0.55, colour = "black") +
  geom_segment(aes(x = CI_low, xend = CI_high, yend = term), linewidth = 1.0) +
  geom_point(aes(x = Effect), size = 3.4) +
  geom_text(aes(x = Effect, label = label), nudge_y = 0.18, size = 4.0) +
  scale_x_log10(
    limits = c(0.10, 2.0),
    breaks = c(0.1, 0.2, 0.5, 1, 2),
    labels = c("0.1", "0.2", "0.5", "1", "2")
  ) +
  labs(
    x = "Incidence rate ratio",
    y = NULL,
    title = "Observed ASV richness (rarefied to 19,000 reads)",
    tag = "A"
  ) +
  base_theme

p_sha <- ggplot(sha_res, aes(y = term)) +
  geom_vline(xintercept = 0, linewidth = 0.55, colour = "black") +
  geom_segment(aes(x = CI_low, xend = CI_high, yend = term), linewidth = 1.0) +
  geom_point(aes(x = Effect), size = 3.4) +
  geom_text(aes(x = Effect, label = label), nudge_y = 0.18, size = 4.0) +
  coord_cartesian(xlim = c(-2.1, 1.1)) +
  labs(
    x = "Estimate",
    y = NULL,
    title = "Shannon diversity (rarefied to 19,000 reads)",
    tag = "B"
  ) +
  base_theme

p_alpha <- p_obs / p_sha

ggsave(
  file.path(out, "Fig_alpha_rarefied_BW.png"),
  p_alpha, width = 10.5, height = 7.2, dpi = 300, bg = "white"
)
ggsave(
  file.path(out, "Fig_alpha_rarefied_BW.pdf"),
  p_alpha, width = 10.5, height = 7.2, bg = "white"
)
if (requireNamespace("svglite", quietly = TRUE)) {
  ggsave(
    file.path(out, "Fig_alpha_rarefied_BW.svg"),
    p_alpha, width = 10.5, height = 7.2,
    device = svglite::svglite, bg = "white"
  )
}

cat("Alpha models and figure complete.\n")
